import pyomo.environ as pyo

DATA = {
    "PRODUCTS": ["bagels", "croissants"],
    "oven_time": {"bagels": 2.0, "croissants": 1.0},
    "chef_time": {"bagels": 0.25, "croissants": 2.0},
    "oven_capacity": 70.0,
    "chef_capacity": 32.0,
    "profit": {"bagels": 20.0, "croissants": 40.0},
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    # Sets
    model.PRODUCTS = pyo.Set(initialize=d["PRODUCTS"])

    # Variables
    model.production = pyo.Var(
        model.PRODUCTS, within=pyo.NonNegativeReals, bounds=(0, None)
    )

    # Objective: maximize total profit
    def obj_rule(m):
        return sum(d["profit"][p] * m.production[p] for p in m.PRODUCTS)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.maximize)

    # Constraint: oven capacity fully used (equality)
    def oven_rule(m):
        return (
            sum(d["oven_time"][p] * m.production[p] for p in m.PRODUCTS)
            == d["oven_capacity"]
        )

    model.oven_capacity = pyo.Constraint(rule=oven_rule)

    # Constraint: pastry chef capacity fully used (equality)
    def chef_rule(m):
        return (
            sum(d["chef_time"][p] * m.production[p] for p in m.PRODUCTS)
            == d["chef_capacity"]
        )

    model.chef_capacity = pyo.Constraint(rule=chef_rule)

    return model


